// 一条场次记录（历史列表与文字演练的"未结束"列表共用）。
// `base` 是点进去之后落到哪个视图：历史里落到 `/`，文字演练里落到 `/text`。
// `withEnd` 为真且这场没结束时，右边多一个「结束面试」按钮。
// `withDelete` 为真时，右边多一个「删除记录」按钮（2026-10-19 用户要的）。
function sessItem(s, base, withEnd, withDelete) {
  var link = sessLink(s, base);
  var actions = "";

  if (withEnd && !s.is_finished) {
    actions += '<button class="endbtn" data-sid="' + esc(s.session_id || "") +
      '">结束面试</button>';
  }
  if (withDelete) {
    actions += '<button class="delbtn" data-sid="' + esc(s.session_id || "") +
      '">删除记录</button>';
  }
  if (!actions) { return link; }
  return '<div class="sess-row">' + link +
    '<div class="sess-actions">' + actions + "</div></div>";
}

