// 所以先让用户确认一次。
function deleteSession(sessionId, btn) {
  if (!sessionId) { return; }
  if (!window.confirm("删除这场面试记录？删除后不可恢复（不生成报告）。")) {
    return;
  }
  if (btn) { btn.disabled = true; btn.textContent = "正在删除…"; }
  fetch("/api/sessions/" + encodeURIComponent(sessionId), { method: "DELETE" })
    .then(function (r) {
      return r.json().then(function (d) {
        if (!r.ok || d.error) { throw new Error(d.error || ("HTTP " + r.status)); }
        return d;
      });
    })
    .then(function () {
      setStatus("ok", "已删除");
      // 删掉的正好是当前打开的那一场：退出它，别停在一个已经不存在的会话上
      if (SID && SID === sessionId && !IS_LIST) {
        history.replaceState(null, "", IS_TEXT ? "/text" : "/");
        SID = "";
      }
      refreshCurrentView();
    })
    .catch(function (e) {
      setStatus("err", e.message);
      if (btn) { btn.disabled = false; btn.textContent = "删除记录"; }
    });
}

