def add_rich(p, text, size=11, base_bold=False):
    """把 **加粗** 渲染成真正的加粗 run，其余原文。"""
    import re as _re
    parts = _re.split(r"(\*\*.+?\*\*)", text)
    for part in parts:
        if not part:
            continue
        if part.startswith("**") and part.endswith("**"):
            run = p.add_run(part[2:-2])
            set_font(run, size=size, bold=True)
        else:
            run = p.add_run(part)
            set_font(run, size=size, bold=base_bold)


def add_para(doc, text, bold=False, size=11, indent=False):
    p = doc.add_paragraph()
    add_rich(p, text, size=size, base_bold=bold)
    if indent:
        p.paragraph_format.first_line_indent = Pt(22)
    p.paragraph_format.space_after = Pt(6)
    return p


